INSERT IGNORE INTO faqs (question, answer, page_key, category, sort_order, is_active) VALUES
  ('Which basmati rice is best for biryani?', 'For biryani, look for extra-long grains with high elongation that stay firm through dum cooking. Naturally aged basmati delivers better texture, grain separation, and the presentation biryani deserves. India Gate Classic and Super are ideal choices.', 'home', NULL, 0, 1),
  ('What makes basmati rice different from regular rice?', 'Basmati is a distinct variety known for its long, slender grains, natural fragrance, and fluffy texture when cooked. Unlike regular rice, basmati elongates significantly during cooking and stays light and separate, not sticky or clumpy.', 'home', NULL, 1, 1),
  ('Why is naturally aged basmati better?', 'Ageing is the hallmark of quality basmati. Through natural ageing, grains develop deeper flavour, finer texture, improved elongation, and more consistent cooking results. It''s what separates refined basmati from ordinary rice.', 'home', NULL, 2, 1),
  ('How do I choose the right rice for different dishes?', 'Match the rice to the meal: Extra-long grain (Classic, Super) for biryani and special pulaos. Long grain (Tibar, Dubar) for everyday premium meals. Medium grain (Everyday, Rozzana) for daily dal-chawal. Regional varieties (Sona Masoori, Ponni, Kolam) for authentic regional dishes.', 'home', NULL, 3, 1),
  ('What makes India Gate trusted by Indian families?', 'Since 1889, India Gate has delivered naturally aged basmati with consistent quality, stone-free, hygienically packed, and untouched by hands. Over 130 years of trust, one grain at a time.', 'home', NULL, 4, 1),
  ('What makes this rice different from regular basmati for biryani?', 'Regular basmati can make good biryani. Biryani Basmati is optimised for biryani. The key differences: (1) Exceptional grain separation — stays individual even under heavy masala and extended dum, (2) Dum-cooking resilience — doesn’t turn mushy after 45 minutes of sealed cooking, (3) 4.0x elongation — grains reach 18.8mm post-cook for impressive visual appeal. If biryani is your signature dish, this rice is engineered for you.', 'products/biryani-basmati-rice', NULL, 0, 1),
  ('Biryani Rice vs Classic — which is better for biryani?', 'Both make excellent biryani, but they serve different needs. Classic is our flagship all-rounder — 2-year aged, extra-long grains with 4.5x elongation, works beautifully for biryani and pulao and special occasions. Biryani Rice is the specialist — specifically engineered for biryani’s unique demands with exceptional grain separation. Choose Classic for versatility; Biryani Rice if biryani is your primary focus.', 'products/biryani-basmati-rice', NULL, 1, 1),
  ('Can I use Biryani Rice for pulao or daily cooking?', 'You can, but it’s overkill. Biryani Rice is optimised for dum cooking and heavy masala absorption — features you don’t need for simple pulao. For pulao, Pulav Rice or Tibar offer better value. For daily cooking, Dubar or Select are more appropriate.', 'products/biryani-basmati-rice', NULL, 2, 1),
  ('What is the best basmati rice for biryani in India?', 'For restaurant-quality biryani at home, you need: (1) extra-long grains for visual appeal, (2) extended ageing for aroma and separation, (3) high elongation for fluffy results. India Gate Classic checks all three — 2-year aged, extra-long grains, 4.5x elongation. It''s specifically designed for dishes where rice is the centrepiece. For everyday biryani, Super or Tibar work well at lower price points.', 'products/classic', NULL, 0, 1),
  ('Classic vs Biryani Special — which is better for biryani?', 'Both are premium options. Classic is our flagship gold standard — 2-year aged, extra-long grains, works brilliantly for biryani AND pulao AND special occasions. Biryani Special is specifically engineered for biryani with optimised grain separation. Choose Classic for versatility across celebrations; Biryani Special if you''re a biryani purist who wants rice designed for that one dish.', 'products/classic', NULL, 1, 1),
  ('Why is aged basmati rice better than fresh basmati?', 'ageing transforms basmati rice. During 2 years of controlled storage, moisture content reduces and starch structure changes. The result: (1) Stronger aroma — the signature basmati fragrance intensifies, (2) Better elongation — grains stretch to 20mm with 4.5x expansion, (3) Exceptional separation — no clumping or sticking, (4) Fluffier texture — lighter, more delicate grains. Fresh basmati can be sticky and lacks the aromatic depth that makes biryani memorable.', 'products/classic', NULL, 2, 1),
  ('Is India Gate Classic worth the premium price?', 'Classic costs more because it delivers more: 2 full years of ageing (most competitors age 12-18 months), hand-selected extra-long grains, 4.5x elongation, and India Gate''s 135-year quality legacy. For everyday meals, our mid-range options like Tibar or Dubar offer excellent value. But for occasions where rice quality is visible and memorable — festivals, guests, celebrations — Classic is the rice that never disappoints.', 'products/classic', NULL, 3, 1),
  ('Which India Gate rice is best for special occasions?', 'For celebrations and special occasions, we recommend: Classic (flagship, 2-year aged, versatile for biryani + pulao), Biryani Special (optimised specifically for biryani), or Super (premium, versatile option at a mid-range price). Classic is the traditional choice for weddings, Eid, Diwali, and family gatherings where the rice needs to impress.', 'products/classic', NULL, 4, 1),
  ('Why is aged rice better for everyday cooking?', 'Aging transforms basmati rice. Naturally aged grains lose excess moisture gradually — developing firmer texture, better expansion during cooking, and more consistent results. Daily Delight is aged, so you get predictable, reliable performance every time you cook. For everyday family meals, that consistency matters.', 'products/daily-delight-basmati-rice', NULL, 0, 1),
  ('How does 1 cup serve 5 people?', 'Short grains expand more than long grains. Daily Delight’s short-grain basmati expands significantly during cooking — 3.6x in volume. This means 1 cup of uncooked rice yields enough for 5 people when cooked. For families cooking daily, this translates to real everyday value.', 'products/daily-delight-basmati-rice', NULL, 1, 1),
  ('Daily Delight vs Mogra — which is better for daily use?', 'Both are great everyday options. Daily Delight uses whole short grains — better texture, consistent cooking, and quality you can see. Mogra uses short grain and offers maximum economy for large batches. Choose Daily Delight for quality + value; Mogra if you’re prioritising pure volume.', 'products/daily-delight-basmati-rice', NULL, 2, 1),
  ('What’s the best way to cook Daily Delight for consistent results?', 'Three keys for fluffy, non-sticky rice: (1) Soak 30 minutes before cooking — ensures even hydration and better expansion, (2) Use 1 cup rice : 2 cups water, (3) Rest 5 minutes after cooking before fluffing. Following these steps gives you the same satisfying results, meal after meal — 3.6x volume expansion every time.', 'products/daily-delight-basmati-rice', NULL, 3, 1),
  ('Is Daily Delight good value for large families?', 'That’s exactly what it’s designed for. Daily Delight’s ‘1 cup serves 5’ efficiency means you use less rice to feed more people — so the pack lasts longer. Combined with whole grain quality and consistent results, it’s the smart choice for families that want good rice without paying a premium.', 'products/daily-delight-basmati-rice', NULL, 4, 1),
  ('What’s the difference between Daily Premium and Everyday rice?', 'The key difference is grain length. Daily Premium has long-slender grains — Flavourful & Fine grain character, naturally aged, priced for daily use. If grain length and lean slender elegance matter to you, Daily Premium is the upgrade. Everyday has medium grains — good quality, balanced value, from our All Rounder range.', 'products/daily-premium-basmati-rice', NULL, 0, 1),
  ('Daily Premium vs Dubar — which should I choose?', 'Both are long-slender, naturally aged, Flavourful & Fine basmati. Daily Premium is the more affordable entry point into long-slender grain territory. Dubar is the everyday premium option with stronger aroma and better overall refinement. Choose Dubar for the best everyday long-grain experience; Daily Premium when you want long grains at a lower price point for daily use.', 'products/daily-premium-basmati-rice', NULL, 1, 1),
  ('Why are long-slender grains better than medium grains?', 'Long-slender grains offer: (1) Better visual appeal — looks more elegant on the plate, (2) Superior elongation — stretches more when cooked, (3) Better separation — less clumping, (4) Enhanced aroma — more refined basmati fragrance. For dishes where rice is visible — pulao, dal-chawal for guests — long-slender grains make a noticeable difference.', 'products/daily-premium-basmati-rice', NULL, 2, 1),
  ('Is Daily Premium good for pulao?', 'Yes — Daily Premium’s long-slender grains work well for pulao. The grains stay separate, absorb spices well, and look elegant. For pulao as the hero dish, you can also consider Pulav Rice (specifically optimised for pulao).', 'products/daily-premium-basmati-rice', NULL, 3, 1),
  ('Which India Gate rice gives the best value for long grains?', 'For long-grain value: Daily Premium is the most affordable Flavourful & Fine long-slender option, followed by Dubar (stronger aroma, everyday premium), then Select (naturally aged, versatile across premium meals). Daily Premium is your entry point — long grains, lean, slender form, without premium pricing.', 'products/daily-premium-basmati-rice', NULL, 4, 1),
  ('What makes Dubar authentic basmati?', 'Dubar is 100% authentic basmati from India Gate — naturally aged to develop refined flavour and superior texture. Every batch meets the quality standards trusted by families for over 130 years. Long slender grains, rich aroma, consistent cooking performance which expands 3.6x in volume upon cooking.', 'products/dubar-basmati-premium-rice', NULL, 0, 1),
  ('Why does natural ageing matter for Dubar?', 'ageing is the mark of quality basmati. Over time, grains develop richer flavour, finer texture, and more consistent cooking performance. Dubar''s natural ageing ensures a superior experience in every meal — the difference is evident from the first bite.', 'products/dubar-basmati-premium-rice', NULL, 1, 1),
  ('Is Dubar good for everyday family cooking?', 'That''s exactly what it''s made for. Dubar is designed for quality seekers who want refined basmati for daily use — dal-chawal, rajma rice, jeera rice, simple pulavs. Premium flavour and texture, every meal, without reservation - expands 3.6x in volume upon cooking.', 'products/dubar-basmati-premium-rice', NULL, 2, 1),
  ('Dubar vs loose rice — why choose Dubar?', 'Dubar has lean and slender grain hygienically packed, naturally aged, and untouched by hands. You get reliable premium quality at a comparable price, with India Gate''s trust behind every grain. Loose or khulla rice is inconsistent — lower quality, uncertain ageing, possible impurities.', 'products/dubar-basmati-premium-rice', NULL, 3, 1),
  ('Dubar vs Tibar — what''s the difference?', 'Both are naturally aged, long-slender grain basmati from the Flavourful & Fine range. Tibar offers a step up in refined flavour and versatility — ideal for occasions as well as daily meals. Dubar is the dependable everyday premium — the same long slender grain quality at a more accessible price point. For everyday dal-chawal and family meals, Dubar delivers everything you need.', 'products/dubar-basmati-premium-rice', NULL, 4, 1),
  ('What makes Everyday Basmati a dependable choice?', 'Everyday is naturally aged basmati with medium grains designed for consistent daily cooking. Every batch delivers fluffy, non-sticky grains with 3.5x elongation — refined flavour and reliable results so you never have to think twice about your rice.', 'products/everyday-basmati-rice', NULL, 0, 1),
  ('Why does natural aging matter for Everyday?', 'Aging is the foundation of quality basmati. Through natural aging, grains develop better texture, improved separation, and consistent cooking performance. Everyday’s aging process ensures the fluffy, non-sticky dependable results — meal after meal.', 'products/everyday-basmati-rice', NULL, 1, 1),
  ('Is Rozzana Basmati rice broken?', 'No — Rozzana is whole grain basmati rice. “Medium grain” refers to the length of the intact grain, not breakage. Each grain is whole, unbroken, and cooks fluffy and non-sticky every time. Within the Rozzana range, all three variants are whole grain: Feast Rozzana is Tibar-grade medium grain with rich aroma and 3.6x elongation, Rozzana Choice is Dubar-grade medium grain for everyday value with 4.0x elongation, and Everyday is the reliable daily medium-grain option with 3.5x elongation. Same authentic basmati character — just in a shorter, everyday-friendly grain format.', 'products/everyday-basmati-rice', NULL, 2, 1),
  ('What dishes is Everyday best suited for?', 'Everyday excels in daily family meals — dal-chawal, khichdi, jeera rice, curd rice, kadhi chawal, and simple pulaos. It’s built for the meals you cook most often, delivering consistent quality and great taste in every serving.', 'products/everyday-basmati-rice', NULL, 3, 1),
  ('Why choose Everyday over loose rice?', 'Everyday is naturally aged, stone-free, and hygienically packed with the same dependable quality in every bag. It delivers 3.5x elongation and fluffy non-sticky grains consistently. Loose or khulla rice varies batch to batch — inconsistent aging, uncertain quality, and possible impurities. The choice for families who rely on their rice every day.', 'products/everyday-basmati-rice', NULL, 4, 1),
  ('Is Feast Rozzana real basmati rice?', 'Yes — authentic basmati rice sourced from the Himalayan basmati belt, naturally aged to develop the characteristic aroma and 3.6x elongation. “Rozzana” simply means “everyday” in Hindi. Feast Rozzana is Tibar-grade medium grain — fluffy, non-sticky, great taste always. The same quality standards India Gate has maintained for over 135 years.', 'products/feast-rozzana-basmati-rice', NULL, 0, 1),
  ('Feast Rozzana vs Rozzana Choice — what’s the difference?', 'Both are All Rounder medium grain basmati. Feast Rozzana is Tibar-grade with 3.6x elongation and richer aroma — the premium option within the range. Rozzana Choice is Dubar-grade with 4.0x elongation and is the most accessible everyday option. Choose Feast Rozzana for noticeably better aroma and quality; Rozzana Choice for maximum everyday value.', 'products/feast-rozzana-basmati-rice', NULL, 1, 1),
  ('Is Rozzana Basmati rice broken?', 'No — Rozzana is whole grain basmati rice. “Medium grain” refers to the length of the intact grain, not breakage. Each grain is whole, unbroken, and cooks fluffy and non-sticky every time. Within the Rozzana range, all three variants are whole grain: Feast Rozzana is Tibar-grade medium grain with rich aroma and 3.6x elongation, Rozzana Choice is Dubar-grade medium grain for everyday value with 4.0x elongation, and Everyday is the reliable daily medium-grain option with 3.5x elongation. Same authentic basmati character — just in a shorter, everyday-friendly grain format.', 'products/feast-rozzana-basmati-rice', NULL, 2, 1),
  ('Can I use Feast Rozzana for biryani?', 'Feast Rozzana works for simple home biryani. For special occasions or restaurant-style biryani with long separate grains, Classic or Biryani Special are the right choices. Feast Rozzana is at its best in everyday dishes where fluffy, non-sticky texture matters most.', 'products/feast-rozzana-basmati-rice', NULL, 3, 1),
  ('What’s the best basmati rice for daily use in India?', 'For daily use, the ideal balance is quality + value + consistency. Feast Rozzana delivers all three — Tibar-grade medium grain, fluffy and non-sticky, 3.6x elongation, great taste always. Designed specifically for families who eat rice every day and want a reliable all rounder.', 'products/feast-rozzana-basmati-rice', NULL, 4, 1),
  ('What is Mini Mogra II rice?', 'Mini Mogra II is the maximum-value aged short grain basmati from India Gate’s Smart Choice range. Naturally aged for authentic basmati aroma and flavour, it delivers 3.9x volume expansion — 1 cup serves 5 people. It’s designed for buyers who want genuine basmati character at the most accessible price point, in bulk packs for large families and commercial kitchens.', 'products/mini-mogra-II-basmati-rice', NULL, 0, 1),
  ('Mini Mogra II vs Mini Mogra — what’s the difference?', 'Both are aged short grain basmati delivering 1 cup serves 5 with 3.9x expansion. Mini Mogra has slightly larger grain pieces, resulting in better texture and visual appeal. Mini Mogra II has smaller grain pieces and is the most economical option in the range. Choose Mini Mogra when texture and presentation matter; Mini Mogra II when maximum economy is the priority.', 'products/mini-mogra-II-basmati-rice', NULL, 1, 1),
  ('Who should buy Mini Mogra II?', 'Mini Mogra II is ideal for: large families (5+ members) eating rice daily, hostel messes and student kitchens, small restaurants and dhabas, caterers and event cooks, tiffin services, and anyone who values basmati aroma but prioritises budget. The 30 KG bulk pack offers the best value for commercial and large-volume cooking.', 'products/mini-mogra-II-basmati-rice', NULL, 2, 1),
  ('Is aged broken basmati as flavorful as whole grain?', 'For flavour and aroma — yes. Basmati character comes from the grain variety and the aging process, not grain length. The natural aging of Mini Mogra II enhances its flavour, aroma, and cooking performance. Where it differs from whole grain: shorter grains, slightly softer texture when cooked — which is ideal for everyday dishes like khichdi and dal-chawal.', 'products/mini-mogra-II-basmati-rice', NULL, 3, 1),
  ('What dishes work best with Mini Mogra II?', 'Mini Mogra II is ideal for everyday dishes where texture is secondary to flavour: dal-chawal, khichdi (the softer grain blends creamily with dal), curd rice (absorbs yoghurt flavours well), and rice kanji. For large-scale cooking in restaurants, community kitchens, and catering, Mini Mogra II delivers reliable basmati quality at scale.', 'products/mini-mogra-II-basmati-rice', NULL, 4, 1),
  ('What is Mini Mogra rice?', 'Mini Mogra is aged short grain basmati rice from India Gate’s Smart Choice range. Sourced from the Himalayan harvest and naturally aged for authentic aroma and flavour, it delivers 3.9x volume expansion — meaning 1 cup serves 5 people. It’s designed for large families and bulk cooking where generous portions at great value are the priority.', 'products/mini-mogra-basmati-rice', NULL, 0, 1),
  ('Mini Mogra vs Mogra — which should I buy?', 'Both are Smart Choice short grain aged basmati delivering 1 cup serves 5. Mogra has larger grain pieces and is available in household packs (1 KG, 5 KG, 10 KG). Mini Mogra is available in bulk packs (5 KG, 10 KG, 30 KG). Choose Mogra for everyday household use; Mini Mogra for large-volume cooking and bulk buying.', 'products/mini-mogra-basmati-rice', NULL, 1, 1),
  ('Mogra vs Daily Delight — which is better for everyday meals?', 'Both are excellent everyday options. Daily Delight uses whole short grains — better visual appeal and texture, ideal for family meals where presentation matters. Mogra uses short grains — slightly softer texture, better suited for khichdi, curd rice, and dishes where grain length is less important. Both give 1 cup serves 5 value.', 'products/mini-mogra-basmati-rice', NULL, 2, 1),
  ('Is Mini Mogra good for large family cooking?', 'That’s exactly what it’s built for. The ‘1 cup serves 5’ yield makes it exceptionally efficient for large families. The 3.9x volume expansion ensures generous portions from every batch, and the natural aging delivers authentic basmati aroma in every meal — consistently, at a great value.', 'products/mini-mogra-basmati-rice', NULL, 3, 1),
  ('What dishes work best with Mini Mogra?', 'Mini Mogra is ideal for everyday dishes where rice is a comforting base: khichdi (the soft grain blends beautifully with dal), curd rice (short grain absorbs yoghurt flavours well), dal-chawal, and rice kanji. For large gatherings and community cooking, Mini Mogra delivers consistent results at scale.', 'products/mini-mogra-basmati-rice', NULL, 4, 1),
  ('What is Mogra rice and how is it different from regular basmati?', 'Mogra is short grain basmati rice — from the same premium Himalayan harvest as whole-grain basmati. The aroma, flavour, and cooking character are unmistakably basmati. With 3.9x volume expansion and length, it delivers generous portions from every cup. For everyday meals where flavour and value matter, Mogra is the smart choice.', 'products/mogra-basmati-rice', NULL, 0, 1),
  ('Why does Mogra have a strong basmati aroma?', 'Basmati aroma comes from the grain variety and the aging process — not grain length. India Gate Mogra comes from the same northwest Himalayan harvest zone as our premium basmati, and it is naturally aged to develop that distinctive fragrance. The aging process is what delivers consistent superior taste and aroma in every meal.', 'products/mogra-basmati-rice', NULL, 1, 1),
  ('Mogra vs Daily Delight — which is better for everyday meals?', 'Both are excellent everyday options. Daily Delight uses whole short grains — better visual appeal and texture, ideal for family meals where presentation matters. Mogra uses short grains — slightly softer texture, better suited for khichdi, curd rice, and dishes where grain length is less important. Both give 1 cup serves 5 value.', 'products/mogra-basmati-rice', NULL, 2, 1),
  ('Is Mogra good for khichdi and curd rice?', 'Yes — khichdi and curd rice are where Mogra excels. The short grain cooks soft and blends beautifully with dal or curd, creating the right texture for these dishes. For khichdi in particular, short grain is actually preferable to long grain because it produces a creamier, more cohesive result.', 'products/mogra-basmati-rice', NULL, 3, 1),
  ('Why is Mogra more affordable than long-grain basmati?', 'Mogra is made from short grain basmati that is priced more accessibly than premium long-grain varieties — even though the flavour, aroma, and origin are from the same Himalayan harvest. This is what makes Mogra the smart choice: genuine basmati character at everyday prices.', 'products/mogra-basmati-rice', NULL, 4, 1),
  ('What is the best rice for pulao?', 'For perfect pulao, you need rice that absorbs spice flavours well, stays light and fluffy (not dense), has long grains for visual appeal, and remains separate after cooking. India Gate Pulav Rice is specifically built for these requirements — 4.0x elongation and calibrated for spice absorption. For everyday pulao without a specialist rice, Tibar and Super also work well as versatile options.', 'products/pulav-premium-rice', NULL, 0, 1),
  ('Pulav Rice vs Biryani Rice — what’s the difference?', 'Different dishes, different rice. Biryani Special is optimised for dum cooking (45+ min sealed), heavy masala layering, and holding form under pressure. Pulav Rice is optimised for lighter texture, spice and ghee absorption, and a delicate aromatic finish. Biryani rice is denser and more resilient; Pulav rice is lighter and more flavour-absorbent. Use each for its intended dish.', 'products/pulav-premium-rice', NULL, 1, 1),
  ('Can I use Pulav Rice for biryani?', 'You can, but it’s not the optimal choice. Pulav Rice is lighter and may not hold up through extended dum cooking the way biryani demands. For biryani — especially celebratory or guest-quality biryani — Biryani Special or Classic are the right choices. Save Pulav Rice for what it does best.', 'products/pulav-premium-rice', NULL, 2, 1),
  ('Pulav Rice vs Tibar — which is better for pulao?', 'Both make excellent pulao. Pulav Rice is the specialist — specifically built for pulao, lighter texture, engineered for spice absorption, 4.0x elongation. Tibar is the versatile all-rounder that works beautifully for pulao as well as daily meals and guest occasions. Choose Pulav Rice if pulao is your primary dish; Tibar if you want one premium rice for multiple uses.', 'products/pulav-premium-rice', NULL, 3, 1),
  ('Why does my pulao turn out mushy or sticky?', 'Common causes: (1) Wrong rice — not all basmati is pulao-optimised, (2) Too much water — pulao needs 1:1.5 ratio, not 1:2, (3) Skipping soak — 20-minute soak helps grains cook evenly, (4) Stirring after cooking — rest the rice, don’t stir. Using Pulav Rice with correct technique solves most common pulao issues.', 'products/pulav-premium-rice', NULL, 4, 1),
  ('What’s the most budget-friendly basmati rice from India Gate?', 'Rozzana Choice is India Gate’s most accessible basmati rice, specifically designed for families who want trusted brand quality with great taste. Dubar-grade medium grain, fluffy & non-sticky, 4.0x elongation. If you’re looking to switch from loose rice to packaged basmati, this is your best entry point.', 'products/rozzana-choice-basmati-rice', NULL, 0, 1),
  ('Is Rozzana Choice real basmati rice?', 'Yes — Rozzana Choice is authentic basmati rice from India Gate, one of India’s most trusted rice brands for over 135 years. “Rozzana” simply means “everyday” in Hindi, indicating it’s made for daily use. Same quality standards, same brand promise, more accessible price.', 'products/rozzana-choice-basmati-rice', NULL, 1, 1),
  ('Is Rozzana Basmati rice broken?', 'No — Rozzana is whole grain basmati rice. “Medium grain” refers to the length of the intact grain, not breakage. Each grain is whole, unbroken, and cooks fluffy and non-sticky every time.Within the Rozzana range, all three variants are whole grain: Feast Rozzana is Tibar-grade medium grain with rich aroma and 3.6x elongation, Rozzana Choice is Dubar-grade medium grain for everyday value with 4.0x elongation, and Everyday is the reliable daily medium-grain option with 3.5x elongation. Same authentic basmati character — just in a shorter, everyday-friendly grain format.', 'products/rozzana-choice-basmati-rice', NULL, 2, 1),
  ('Rozzana Choice vs Feast Rozzana — what’s the difference?', 'Both are All Rounder medium grain basmati. Feast Rozzana is Tibar-grade with richer aroma and 3.6x elongation — the premium step-up within the range. Rozzana Choice is Dubar-grade with 4.0x elongation and is the most accessible everyday option. Choose Feast Rozzana when you want noticeably better quality; Rozzana Choice for maximum everyday value.', 'products/rozzana-choice-basmati-rice', NULL, 3, 1),
  ('Why choose packaged basmati over loose rice?', 'Packaged basmati like Rozzana Choice offers: guaranteed stone-free grains, consistent quality batch to batch, no adulteration, hygienic handling throughout the supply chain, and proper aging. Loose or khulla rice varies in quality, aging, and purity — and is often touched by hands during handling. The quality advantage is real.', 'products/rozzana-choice-basmati-rice', NULL, 4, 1),
  ('What makes Select Basmati special for regional cooking?', 'Select is naturally aged — developing depth of flavour, superior grain separation reaching 3.8x expansion, and the refined texture that rice-forward regional dishes demand. When the rice is the centrepiece of the meal (not just a side), that extra aging and quality make the difference between good and great.', 'products/select-premium-rice', NULL, 0, 1),
  ('What dishes is Select best suited for?', 'Select excels in rice-forward regional favourites where every grain matters: rajma chawal, kadhi chawal, sambhar rice, lemon rice, curd rice, vangi bhaat, Chettinad curries. For these dishes, grain separation and flavour absorption are critical — Select’s natural aging and long-slender grain deliver both.', 'products/select-premium-rice', NULL, 1, 1),
  ('Why choose naturally aged rice for regional dishes?', 'Natural aging is the hallmark of quality basmati. Through extended aging, grains develop richer flavour, better separation during cooking, and finer texture. For regional dishes like rajma chawal where rice absorbs the curry’s flavour, an aged grain tastes markedly better than fresh or under-aged alternatives', 'products/select-premium-rice', NULL, 2, 1),
  ('How do I cook Select for best results?', 'Soak 20–30 minutes before cooking. Use 1 cup rice : 2 cups water. Rest 5 minutes after cooking, then fluff gently. These steps maximise grain separation and refined texture — 3.8x expansion in volume after cooking.', 'products/select-premium-rice', NULL, 3, 1),
  ('Select vs Dubar — what’s the difference?', 'Both are naturally aged, long-slender grain basmati from the Flavourful & Fine range. The key difference is specialisation. Dubar is the everyday premium — ideal for daily dal-chawal and family meals. Select is specifically tuned for premium feasting where rice is the star. Choose Select when the recipe calls for flavour absorption and grain separation to be at their best.', 'products/select-premium-rice', NULL, 4, 1),
  ('What makes Super a premium choice within Flavourful & Fine?', 'Super stands apart in the range with two distinct claims: Extra Long Grain — and Perfectly Aged from True Origin Himalayan basmati. The result is a rice with exceptional 4.2x elongation, elevated visual appeal, and refined texture that makes it the versatile premium for meals where both flavour and presentation matter.', 'products/super-basmati-premium-rice', NULL, 0, 1),
  ('Why does ‘perfectly aged’ matter for Super?', 'Perfect aging for 2 years develops the grain to its full potential — deeper flavour, exceptional elongation during cooking, and the finer texture that distinguishes premium basmati. Super’s aging process is what unlocks the 4.2x elongation, and the aromatic depth that elevates every dish.', 'products/super-basmati-premium-rice', NULL, 1, 1),
  ('What dishes is Super best suited for?', 'Super excels in presentation-forward dishes where grain length, separation, and visual appeal matter: pulao, dum biryani, fried rice, and special occasion meals. The extra-long grains elongate beautifully and stay separate, making every serving look as impressive as it tastes.', 'products/super-basmati-premium-rice', NULL, 2, 1),
  ('How do I cook Super for best results?', 'Soak 30 minutes for maximum elongation. Use 1 cup rice : 2 cups water. Rest 5 minutes after cooking before fluffing gently. These steps ensure beautifully elongated, separate grains with refined texture every time.', 'products/super-basmati-premium-rice', NULL, 3, 1),
  ('Super vs Classic — when should I choose each?', 'Classic is India Gate’s Gold Standard — 2-year aged, extra-long grains with 4.5x elongation, the flagship for biryani and celebrations. Super is the versatile premium — perfectly aged with 4.2x elongation, ideal for elevated everyday meals, pulao, and occasions where you want premium quality without reaching for the very top. Choose Classic for celebrations; choose Super for elevated everyday dining.', 'products/super-basmati-premium-rice', NULL, 4, 1),
  ('What makes Tibar authentic basmati?', 'Tibar is authentic basmati rice from India Gate — naturally aged to develop refined flavour and superior texture. The aging process, a hallmark of quality basmati, ensures consistent cooking results and the lean, slender elegance expected from the Flavourful & Fine range. Each grain reaches 3.8x expansion in volume.', 'products/tibar-basmati-rice', NULL, 0, 1),
  ('Why is naturally aged rice better?', 'Natural aging allows the grain to mature gradually, developing deeper flavour, finer texture, and reliable cooking performance. It’s the traditional mark of quality that separates refined basmati from ordinary rice. Tibar’s natural aging is what delivers that consistent superior experience in every meal.', 'products/tibar-basmati-rice', NULL, 1, 1),
  ('Is Tibar suitable for both daily meals and special occasions?', 'Absolutely. Tibar is designed for quality seekers who want elevated rice for everyday cooking without reserving it only for guests. The lean, elegant grains and refined taste work beautifully for pulao, steamed rice, biryani, kadhi chawal, and family dinners alike. One rice, every table.', 'products/tibar-basmati-rice', NULL, 2, 1),
  ('What’s the best way to cook Tibar for consistent results?', 'Soak 20–30 minutes for optimal elongation. Use 1 cup rice : 2 cups water. Rest 5 minutes after cooking, then fluff gently. These steps deliver the same refined, separate grains every time — 3.8x expansion in volume when cooked.', 'products/tibar-basmati-rice', NULL, 3, 1),
  ('Tibar vs Dubar — which should I choose?', 'Dubar is an excellent everyday premium option — long-slender grains, naturally aged, ideal for daily dal-chawal and simple dishes. Tibar offers a step up in refined flavour and versatility — it moves seamlessly from weeknight meals to guest occasions. If you want one rice for both, Tibar is the choice.', 'products/tibar-basmati-rice', NULL, 4, 1),
  ('Which basmati rice is best for biryani?', 'For biryani you want long, well-aged grains that stay separate and fluffy after cooking. Our Classic and Super Basmati ranges are aged specifically for that texture.', 'faqs-hub', 'general', 0, 1),
  ('What makes basmati rice different from regular rice?', 'Basmati is a distinct variety known for its long, slender grains, natural fragrance, and fluffy texture when cooked. Unlike regular rice, basmati elongates significantly during cooking and stays light and separate — not sticky or clumpy.', 'faqs-hub', 'general', 1, 1),
  ('Why is naturally aged basmati better?', 'Ageing reduces moisture in the grain, which lets it elongate more during cooking and firms up the texture so it holds its shape instead of turning mushy.', 'faqs-hub', 'general', 2, 1),
  ('How do I choose the right rice for different dishes?', 'Longer, more aged grains suit biryanis and pulaos where separation matters, while shorter or less aged grains work well for everyday steamed rice and simpler meals.', 'faqs-hub', 'general', 3, 1),
  ('What makes India Gate trusted by Indian families?', 'Decades of consistent quality, strict sourcing standards, and a naturally aged process that families have relied on across generations.', 'faqs-hub', 'general', 4, 1),
